package settlementstore

import "database/sql"

func EnsureSchema(db *sql.DB) error {
	_, err := db.Exec(`CREATE TABLE IF NOT EXISTS settlement_instructions (id TEXT PRIMARY KEY, client_ref TEXT NOT NULL UNIQUE, provider_ref TEXT NOT NULL DEFAULT '', beneficiary TEXT NOT NULL, amount_minor BIGINT NOT NULL CHECK (amount_minor > 0), currency TEXT NOT NULL, purpose TEXT NOT NULL DEFAULT '', state TEXT NOT NULL, supersedes TEXT NULL, created_at TIMESTAMPTZ NOT NULL, updated_at TIMESTAMPTZ NOT NULL); ALTER TABLE settlement_instructions ADD COLUMN IF NOT EXISTS institution_id text NOT NULL DEFAULT ''; ALTER TABLE settlement_instructions ADD COLUMN IF NOT EXISTS trade_id text; ALTER TABLE settlement_instructions ADD COLUMN IF NOT EXISTS quote_id text NOT NULL DEFAULT ''; ALTER TABLE settlement_instructions ADD COLUMN IF NOT EXISTS correlation_id text NOT NULL DEFAULT ''; ALTER TABLE settlement_instructions ADD COLUMN IF NOT EXISTS provider_id text NOT NULL DEFAULT 'sim_lp_1'; ALTER TABLE settlement_instructions ADD COLUMN IF NOT EXISTS bank_code text NOT NULL DEFAULT ''; ALTER TABLE settlement_instructions ADD COLUMN IF NOT EXISTS account_number text NOT NULL DEFAULT ''; CREATE UNIQUE INDEX IF NOT EXISTS settlement_one_per_trade ON settlement_instructions(trade_id) WHERE trade_id IS NOT NULL; CREATE INDEX IF NOT EXISTS settlement_customer_report_idx ON settlement_instructions(institution_id,state,currency,updated_at DESC); CREATE TABLE IF NOT EXISTS settlement_transitions (id BIGSERIAL PRIMARY KEY, settlement_id TEXT NOT NULL REFERENCES settlement_instructions(id), from_state TEXT NOT NULL, to_state TEXT NOT NULL, event TEXT NOT NULL, reason TEXT NOT NULL, source TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL); CREATE INDEX IF NOT EXISTS settlement_report_transition_idx ON settlement_transitions(settlement_id,to_state,occurred_at DESC); CREATE TABLE IF NOT EXISTS settlement_evidence (evidence_id TEXT PRIMARY KEY, settlement_id TEXT NOT NULL REFERENCES settlement_instructions(id), provider TEXT NOT NULL, method TEXT NOT NULL, request_ref TEXT NOT NULL, raw_payload_hash TEXT NOT NULL, parsed_at TIMESTAMPTZ NOT NULL, correlation_id TEXT NOT NULL); CREATE TABLE IF NOT EXISTS settlement_finality_outbox (event_id TEXT PRIMARY KEY, institution_id TEXT NOT NULL, settlement_id TEXT NOT NULL REFERENCES settlement_instructions(id), trade_id TEXT NOT NULL, status TEXT NOT NULL CHECK (status IN ('CONFIRMED','FAILED')), correlation_id TEXT NOT NULL, occurred_at TIMESTAMPTZ NOT NULL, delivered_at TIMESTAMPTZ); CREATE INDEX IF NOT EXISTS settlement_finality_pending ON settlement_finality_outbox(occurred_at,event_id) WHERE delivered_at IS NULL;`)
	return err
}
